#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <immintrin.h>

typedef struct {
    uint64_t w[4];
    int len;
    char name[64];
} StationInfo;

StationInfo stations[500];
int num_stations = 0;

void load_stations(const char *path) {
    FILE *f = fopen(path, "r");
    char line[512];
    while (fgets(line, sizeof(line), f)) {
        char *semi = strchr(line, ';');
        if (!semi) continue;
