                    break;
                }
            }
            if (!found) {
                MergedStation *m = &merged[merged_count++];
                memcpy(m->name, name_buf, e->len);
                m->name[e->len] = '\0';
                m->len = e->len;
                m->min = e->min;
                m->max = e->max;
                m->sum = e->sum;
