    while (1) {
        HashEntry *e = &td->table[idx];
        if (__builtin_expect(e->count == 0, 0)) {
            e->vec = masked;
            e->len = len;
            e->min = temp;
            e->max = temp;
            e->sum = temp;
            e->count = 1;
            td->count++;
            return;
