#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <pthread.h>
#include <sched.h>
#include <immintrin.h>
#include <math.h>

#define TABLE_SIZE 4096
#define TABLE_MASK (TABLE_SIZE - 1)

typedef struct {
    __m256i vec;
    int32_t len;
    int32_t min;
    int32_t max;
    int32_t pad;
    int64_t sum;
    int64_t count;
} HashEntry __attribute__((aligned(64)));

typedef struct {
    HashEntry table[TABLE_SIZE];
    int count;
} ThreadData;

typedef struct {
    const char *data;
    size_t start;
    size_t end;
    size_t total_size;
    ThreadData *td;
    int cpu_id;
