#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct {
    char name[128];
    long long sum;
    int count;
    int min;
    int max;
} Station;

#define HASH_SIZE 16384

typedef struct HashNode {
    Station station;
    struct HashNode *next;
} HashNode;

HashNode *hash_table[HASH_SIZE];
Station *all_stations[10000];
int station_count = 0;

static unsigned int hash_str(const char *str, int len) {
    unsigned int hash = 5381;
    for (int i = 0; i < len; i++) {
        hash = ((hash << 5) + hash) + (unsigned char)str[i];
    }
    return hash % HASH_SIZE;
}

static Station *get_or_create(const char *name, int len) {
    unsigned int h = hash_str(name, len);
    HashNode *node = hash_table[h];
    while (node) {
        if (strncmp(node->station.name, name, len) == 0 && node->station.name[len] == '\0') {
            return &node->station;
        }
        node = node->next;
    }
    node = (HashNode *)calloc(1, sizeof(HashNode));
    memcpy(node->station.name, name, len);
    node->station.name[len] = '\0';
    node->station.min = 10000;
    node->station.max = -10000;
    node->station.sum = 0;
    node->station.count = 0;
    node->next = hash_table[h];
    hash_table[h] = node;
    all_stations[station_count++] = &node->station;
    return &node->station;
}

static int compare_stations(const void *a, const void *b) {
    const Station *sa = *(const Station **)a;
    const Station *sb = *(const Station **)b;
    return strcmp(sa->name, sb->name);
}

int main(int argc, char **argv) {
    if (argc < 2) return 1;
    FILE *f = fopen(argv[1], "r");
    if (!f) return 1;

    char line[512];
    while (fgets(line, sizeof(line), f)) {
        char *semi = strrchr(line, ';');
        if (!semi) continue;
        *semi = '\0';
        char *temp_str = semi + 1;

        int sign = 1;
        if (*temp_str == '-') {
            sign = -1;
            temp_str++;
        }
        int temp = 0;
        while (*temp_str >= '0' && *temp_str <= '9') {
            temp = temp * 10 + (*temp_str - '0');
            temp_str++;
        }
        if (*temp_str == '.') {
            temp_str++;
            if (*temp_str >= '0' && *temp_str <= '9') {
                temp = temp * 10 + (*temp_str - '0');
            }
        }
        temp *= sign;

        Station *st = get_or_create(line, semi - line);
        if (temp < st->min) st->min = temp;
        if (temp > st->max) st->max = temp;
        st->sum += temp;
        st->count++;
    }
    fclose(f);

    qsort(all_stations, station_count, sizeof(Station *), compare_stations);

    putchar('{');
    for (int i = 0; i < station_count; i++) {
        Station *st = all_stations[i];
        double mean = (double)st->sum / (double)st->count / 10.0;
        double scaled = mean * 10.0;
        double r = (scaled >= 0) ? floor(scaled + 0.5) : ceil(scaled - 0.5);
        double v = r / 10.0;
        if (fabs(v) < 1e-9) v = 0.0;

        double min_val = st->min / 10.0;
        double max_val = st->max / 10.0;

        printf("%s=%.1f/%.1f/%.1f%s", st->name, min_val, v, max_val, (i + 1 < station_count) ? ", " : "");
    }
    putchar('}');
    putchar('\n');
    return 0;
}

