#include <immintrin.h>

// Parse via branchless / arithmetic
static inline int parse_temp_branchless(const char *p, int *out_len) {
    uint32_t w = *(const uint32_t *)p;
    // Check if first char is '-' (0x2D)
    int is_neg = ((w & 0xFF) == 0x2D);
    w >>= (is_neg * 8);

    // If format is D.D: byte 0 = D, byte 1 = '.', byte 2 = D
    // If format is DD.D: byte 0 = D, byte 1 = D, byte 2 = '.'
    // In little endian:
    // If byte 1 == '.' (0x2E):
    // temp = (byte 0 - '0')*10 + (byte 2 - '0')
    // length consumed = is_neg + 4 (since \n is at byte 3)
    // Else:
    // byte 3 is the decimal digit!
    // temp = (byte 0 - '0')*100 + (byte 1 - '0')*10 + (byte 3 - '0')
    // length consumed = is_neg + 5 (since \n is at byte 4)

    int is_dot1 = ((w & 0xFF00) == 0x2E00);
    int d0 = (w & 0xFF) - '0';
    int d1 = ((w >> 8) & 0xFF) - '0';
    int d2 = ((w >> 16) & 0xFF) - '0';
    int d3 = ((w >> 24) & 0xFF) - '0';

    int val;
    if (is_dot1) {
        val = d0 * 10 + d2;
        *out_len = is_neg + 4;
    } else {
        val = d0 * 100 + d1 * 10 + d3;
        *out_len = is_neg + 5;
    }
    return is_neg ? -val : val;
}

// Parse via pure bit-math (branchless)
static inline int parse_temp_pure_branchless(const char *p, int *out_len) {
    uint64_t w = *(const uint64_t *)p;
    int is_neg = ((w & 0xFF) == 0x2D);
    w >>= (is_neg * 8);

    int is_dot1 = ((w & 0xFF00) == 0x2E00); // 1 if D.D, 0 if DD.D
    // If is_dot1 == 1: digits are at byte 0 and byte 2.
    // If is_dot1 == 0: digits are at byte 0, 1, and 3.
    // Notice:
    // (w & 0x0F) is d0
    // ((w >> 8) & 0x0F) is d1 (or '.' if dot1)
    // ((w >> 16) & 0x0F) is d2 (decimal if dot1)
    // ((w >> 24) & 0x0F) is d3 (decimal if !dot1)

    int val_dot1 = (int)(w & 0x0F) * 10 + (int)((w >> 16) & 0x0F);
    int val_dot2 = (int)(w & 0x0F) * 100 + (int)((w >> 8) & 0x0F) * 10 + (int)((w >> 24) & 0x0F);
    int val = is_dot1 ? val_dot1 : val_dot2;
    *out_len = is_neg + 5 - is_dot1;
    return is_neg ? -val : val;
}

int main() {
    const char *cases[] = {"1.2\n", "-1.2\n", "12.3\n", "-12.3\n", "0.0\n", "-99.9\n"};
    for (int i = 0; i < 6; i++) {
        int l1, l2;
        int v1 = parse_temp_branchless(cases[i], &l1);
        int v2 = parse_temp_pure_branchless(cases[i], &l2);
        printf("%s -> v1=%d (len=%d), v2=%d (len=%d)\n", cases[i], v1, l1, v2, l2);
    }
    return 0;
}

