} StationInfo;

StationInfo stations[500];
int num_stations = 0;

void load_stations(const char *path) {
    FILE *f = fopen(path, "r");
    char line[512];
    while (fgets(line, sizeof(line), f)) {
        char *semi = strchr(line, ';');
        if (!semi) continue;
        *semi = '\0';
        int len = semi - line;
        int found = 0;
        for (int i = 0; i < num_stations; i++) {
            if (stations[i].len == len && strcmp(stations[i].name, line) == 0) {
                found = 1;
                break;
            }
        }
        if (!found) {
            strcpy(stations[num_stations].name, line);
            stations[num_stations].len = len;
            memset(stations[num_stations].w, 0, 32);
            memcpy(stations[num_stations].w, line, len <= 32 ? len : 32);
            num_stations++;
        }
        if (num_stations == 413) break;
    }
    fclose(f);
    printf("Loaded %d stations\n", num_stations);
}

int main() {
    load_stations("/data/measurements-dev.txt");

    // Test hash formulas for table sizes 4096, 8192, 16384
    int sizes[] = {2048, 4096, 8192, 16384};
    for (int s = 0; s < 4; s++) {
        int tsize = sizes[s];
        int mask = tsize - 1;
        uint8_t seen[65536];

        for (uint64_t seed = 0; seed < 1000000; seed++) {
            memset(seen, 0, tsize);
            int coll = 0;
            for (int i = 0; i < num_stations; i++) {
                uint64_t h = _mm_crc32_u64(seed, stations[i].w[0] ^ stations[i].w[1] ^ stations[i].w[2] ^ (uint64_t)stations[i].len);
                int idx = h & mask;
                if (seen[idx]) { coll = 1; break; }
                seen[idx] = 1;
            }
            if (!coll) {
                printf("Table size %d: Found CRC32(w0 ^ w1 ^ w2 ^ len) seed = %lu!\n", tsize, seed);
                break;
            }
        }

        for (uint64_t seed = 0; seed < 1000000; seed++) {
            memset(seen, 0, tsize);
            int coll = 0;
            for (int i = 0; i < num_stations; i++) {
                uint64_t h = _mm_crc32_u64(seed, stations[i].w[0]);
                h = _mm_crc32_u64(h, stations[i].w[1] ^ stations[i].w[2] ^ stations[i].len);
                int idx = h & mask;
                if (seen[idx]) { coll = 1; break; }
                seen[idx] = 1;
            }
            if (!coll) {
                printf("Table size %d: Found 2-step CRC32 seed = %lu!\n", tsize, seed);
                break;
            }
        }
    }
    return 0;
