static inline int parse_temp(const char *p, const char **next_ptr) {
    uint64_t w = *(const uint64_t *)p;
    int is_neg = ((w & 0xFF) == 0x2D);
    w >>= (is_neg * 8);

    int is_dot1 = ((w & 0xFF00) == 0x2E00);
