    }
    return is_neg ? -val : val;
}

static inline void process_entry_1(ThreadData *td, uint64_t w0, int len, int temp) {
    uint64_t h = _mm_crc32_u64(0, w0);
    int idx = (int)(h & TABLE_MASK);

    while (1) {
        HashEntry *e = &td->table[idx];
        if (__builtin_expect(e->count == 0, 0)) {
            e->w[0] = w0;
            e->w[1] = 0;
            e->w[2] = 0;
            e->w[3] = 0;
            e->len = len;
            e->min = temp;
            e->max = temp;
            e->sum = temp;
            e->count = 1;
            td->count++;
            return;
        }
        if (__builtin_expect(e->len == len && e->w[0] == w0 && e->w[1] == 0, 1)) {
            if (temp < e->min) e->min = temp;
            if (temp > e->max) e->max = temp;
            e->sum += temp;
            e->count++;
            return;
        }
        idx = (idx + 1) & TABLE_MASK;
    }
}

static inline void process_entry_2(ThreadData *td, uint64_t w0, uint64_t w1, int len, int temp) {
    uint64_t h = _mm_crc32_u64(w0, w1);
    int idx = (int)(h & TABLE_MASK);

    while (1) {
        HashEntry *e = &td->table[idx];
        if (__builtin_expect(e->count == 0, 0)) {
            e->w[0] = w0;
