            if (temp < e->min) e->min = temp;
            if (temp > e->max) e->max = temp;
            e->sum += temp;
            e->count++;
            return;
        }
        idx = (idx + 1) & TABLE_MASK;
    }
}

static inline void process_entry_n(ThreadData *td, uint64_t w0, uint64_t w1, uint64_t w2, uint64_t w3, int len, int temp) {
    uint64_t h = _mm_crc32_u64(_mm_crc32_u64(w0, w1), w2 ^ (uint64_t)len);
    int idx = (int)(h & TABLE_MASK);

    while (1) {
        HashEntry *e = &td->table[idx];
        if (__builtin_expect(e->count == 0, 0)) {
            e->w[0] = w0;
            e->w[1] = w1;
            e->w[2] = w2;
            e->w[3] = w3;
            e->len = len;
            e->min = temp;
            e->max = temp;
            e->sum = temp;
            e->count = 1;
            td->count++;
            return;
        }
        if (__builtin_expect(e->len == len && ((e->w[0] ^ w0) | (e->w[1] ^ w1) | (e->w[2] ^ w2) | (e->w[3] ^ w3)) == 0, 1)) {
            if (temp < e->min) e->min = temp;
            if (temp > e->max) e->max = temp;
            e->sum += temp;
            e->count++;
            return;
        }
        idx = (idx + 1) & TABLE_MASK;
    }
}

static const uint64_t SEMI_MASK = 0x3B3B3B3B3B3B3B3BULL;
static const uint64_t ONES = 0x0101010101010101ULL;
static const uint64_t HIGHS = 0x8080808080808080ULL;

static void *worker_thread(void *arg) {
    ThreadArg *targ = (ThreadArg *)arg;
    const char *ptr = targ->data + targ->start;
    const char *end = targ->data + targ->end;
    const char *file_end = targ->data + targ->total_size;
    ThreadData *td = targ->td;

    while (ptr < end && ptr + 32 <= file_end) {
        uint64_t w0 = *(const uint64_t *)ptr;
        uint64_t x0 = w0 ^ SEMI_MASK;
        uint64_t m0 = (x0 - ONES) & ~x0 & HIGHS;

        if (m0 != 0) {
            int len = __builtin_ctzll(m0) >> 3;
            uint64_t name0 = _bzhi_u64(w0, len * 8);
            const char *p = ptr + len + 1;
            const char *next_ptr;
            int temp = parse_temp(p, &next_ptr);
            process_entry_1(td, name0, len, temp);
            ptr = next_ptr;
            continue;
        }

        uint64_t w1 = *(const uint64_t *)(ptr + 8);
        uint64_t x1 = w1 ^ SEMI_MASK;
        uint64_t m1 = (x1 - ONES) & ~x1 & HIGHS;

        if (m1 != 0) {
            int len2 = __builtin_ctzll(m1) >> 3;
            int len = 8 + len2;
            uint64_t name1 = _bzhi_u64(w1, len2 * 8);
            const char *p = ptr + len + 1;
            const char *next_ptr;
            int temp = parse_temp(p, &next_ptr);
            process_entry_2(td, w0, name1, len, temp);
            ptr = next_ptr;
            continue;
        }

        uint64_t w2 = *(const uint64_t *)(ptr + 16);
        uint64_t x2 = w2 ^ SEMI_MASK;
        uint64_t m2 = (x2 - ONES) & ~x2 & HIGHS;

        if (m2 != 0) {
            int len3 = __builtin_ctzll(m2) >> 3;
            int len = 16 + len3;
            uint64_t name2 = _bzhi_u64(w2, len3 * 8);
            const char *p = ptr + len + 1;
            const char *next_ptr;
            int temp = parse_temp(p, &next_ptr);
            process_entry_n(td, w0, w1, name2, 0, len, temp);
            ptr = next_ptr;
            continue;
        }

        uint64_t w3 = *(const uint64_t *)(ptr + 24);
        uint64_t x3 = w3 ^ SEMI_MASK;
        uint64_t m3 = (x3 - ONES) & ~x3 & HIGHS;

        if (m3 != 0) {
            int len4 = __builtin_ctzll(m3) >> 3;
            int len = 24 + len4;
            uint64_t name3 = _bzhi_u64(w3, len4 * 8);
            const char *p = ptr + len + 1;
            const char *next_ptr;
            int temp = parse_temp(p, &next_ptr);
            process_entry_n(td, w0, w1, w2, name3, len, temp);
            ptr = next_ptr;
            continue;
        }

        // Fallback for extremely long lines
        const char *semi = memchr(ptr, ';', file_end - ptr);
        if (!semi) break;
        int len = semi - ptr;
        uint64_t w[4] = {0};
        memcpy(w, ptr, len < 32 ? len : 32);
        const char *p = semi + 1;
        const char *next_ptr;
        int temp = parse_temp(p, &next_ptr);
        process_entry_n(td, w[0], w[1], w[2], w[3], len, temp);
        ptr = next_ptr;
    }

    // Boundary fallback
    while (ptr < end && ptr < file_end) {
        const char *semi = memchr(ptr, ';', file_end - ptr);
        if (!semi) break;
        int len = semi - ptr;
        uint64_t w[4] = {0};
        memcpy(w, ptr, len < 32 ? len : 32);
        const char *p = semi + 1;
        const char *next_ptr;
        int temp = parse_temp(p, &next_ptr);
        process_entry_n(td, w[0], w[1], w[2], w[3], len, temp);
        ptr = next_ptr;
    }

    return NULL;
}

typedef struct {
