    while (1) {
        HashEntry *e = &td->table[idx];
        if (__builtin_expect(e->count == 0, 0)) {
            e->w[0] = w0;
            e->w[1] = 0;
            e->w[2] = 0;
            e->w[3] = 0;
            e->len = len;
            e->min = temp;
            e->max = temp;
            e->sum = temp;
            e->count = 1;
            td->count++;
            return;
        }
        if (__builtin_expect(e->len == len && e->w[0] == w0 && e->w[1] == 0, 1)) {
            if (temp < e->min) e->min = temp;
            if (temp > e->max) e->max = temp;
            e->sum += temp;
            e->count++;
            return;
        }
        idx = (idx + 1) & TABLE_MASK;
    }
}

static inline void process_entry_med(ThreadData *td, uint64_t w0, uint64_t w1, int len, int temp) {
    uint64_t h = _mm_crc32_u64(w0, w1);
    int idx = (int)(h & TABLE_MASK);

    while (1) {
        HashEntry *e = &td->table[idx];
        if (__builtin_expect(e->count == 0, 0)) {
            e->w[0] = w0;
            e->w[1] = w1;
            e->w[2] = 0;
            e->w[3] = 0;
            e->len = len;
            e->min = temp;
            e->max = temp;
            e->sum = temp;
            e->count = 1;
            td->count++;
            return;
        }
        if (__builtin_expect(e->len == len && e->w[0] == w0 && e->w[1] == w1 && e->w[2] == 0, 1)) {
            if (temp < e->min) e->min = temp;
            if (temp > e->max) e->max = temp;
            e->sum += temp;
            e->count++;
            return;
        }
        idx = (idx + 1) & TABLE_MASK;
    }
}

static inline void process_entry_long(ThreadData *td, uint64_t w0, uint64_t w1, uint64_t w2, uint64_t w3, int len, int temp) {
    uint64_t h = _mm_crc32_u64(_mm_crc32_u64(w0, w1), w2 ^ (uint64_t)len);
    int idx = (int)(h & TABLE_MASK);

    while (1) {
        HashEntry *e = &td->table[idx];
        if (__builtin_expect(e->count == 0, 0)) {
            e->w[0] = w0;
            e->w[1] = w1;
            e->w[2] = w2;
            e->w[3] = w3;
            e->len = len;
            e->min = temp;
            e->max = temp;
            e->sum = temp;
            e->count = 1;
            td->count++;
            return;
        }
        if (__builtin_expect(e->len == len && ((e->w[0] ^ w0) | (e->w[1] ^ w1) | (e->w[2] ^ w2) | (e->w[3] ^ w3)) == 0, 1)) {
            if (temp < e->min) e->min = temp;
            if (temp > e->max) e->max = temp;
            e->sum += temp;
            e->count++;
            return;
        }
        idx = (idx + 1) & TABLE_MASK;
    }
}

static void *worker_thread(void *arg) {
    ThreadArg *targ = (ThreadArg *)arg;
    const char *ptr = targ->data + targ->start;
    const char *end = targ->data + targ->end;
    const char *file_end = targ->data + targ->total_size;
    ThreadData *td = targ->td;

    const __m256i semi_vec = _mm256_set1_epi8(';');

    while (ptr < end && ptr + 32 <= file_end) {
        __m256i raw = _mm256_loadu_si256((const __m256i *)ptr);
        __m256i cmp = _mm256_cmpeq_epi8(raw, semi_vec);
        int mask = _mm256_movemask_epi8(cmp);

        if (__builtin_expect(mask != 0, 1)) {
            int len = __builtin_ctz(mask);
            const char *p = ptr + len + 1;
            const char *next_ptr;
            int temp = parse_temp_fast(p, &next_ptr);

            if (len < 8) {
                uint64_t w0 = *(const uint64_t *)ptr;
                uint64_t name0 = _bzhi_u64(w0, len * 8);
                process_entry_short(td, name0, len, temp);
            } else if (len < 16) {
                uint64_t w0 = *(const uint64_t *)ptr;
                uint64_t w1 = *(const uint64_t *)(ptr + 8);
                uint64_t name1 = _bzhi_u64(w1, (len - 8) * 8);
                process_entry_med(td, w0, name1, len, temp);
            } else if (len < 24) {
                uint64_t w0 = *(const uint64_t *)ptr;
                uint64_t w1 = *(const uint64_t *)(ptr + 8);
                uint64_t w2 = *(const uint64_t *)(ptr + 16);
                uint64_t name2 = _bzhi_u64(w2, (len - 16) * 8);
                process_entry_long(td, w0, w1, name2, 0, len, temp);
            } else {
                uint64_t w0 = *(const uint64_t *)ptr;
                uint64_t w1 = *(const uint64_t *)(ptr + 8);
                uint64_t w2 = *(const uint64_t *)(ptr + 16);
                uint64_t w3 = *(const uint64_t *)(ptr + 24);
                uint64_t name3 = _bzhi_u64(w3, (len - 24) * 8);
                process_entry_long(td, w0, w1, w2, name3, len, temp);
            }
            ptr = next_ptr;
        } else {
            // Fallback for lines where ';' is beyond 32 bytes
            const char *semi = memchr(ptr, ';', file_end - ptr);
            if (!semi) break;
            int len = semi - ptr;
            uint64_t w[4] = {0};
            memcpy(w, ptr, len < 32 ? len : 32);
            const char *p = semi + 1;
            const char *next_ptr;
            int temp = parse_temp_fast(p, &next_ptr);
            process_entry_long(td, w[0], w[1], w[2], w[3], len, temp);
            ptr = next_ptr;
        }
    }

    // Boundary fallback
    while (ptr < end && ptr < file_end) {
        const char *semi = memchr(ptr, ';', file_end - ptr);
        if (!semi) break;
        int len = semi - ptr;
        uint64_t w[4] = {0};
        memcpy(w, ptr, len < 32 ? len : 32);
        const char *p = semi + 1;
        const char *next_ptr;
        int temp = parse_temp_fast(p, &next_ptr);
        process_entry_long(td, w[0], w[1], w[2], w[3], len, temp);
        ptr = next_ptr;
    }

    return NULL;
}

typedef struct {
    char name[64];
    int len;
    int min;
    int max;
    int64_t sum;
    int64_t count;
} MergedStation;

static int compare_merged(const void *a, const void *b) {
    const MergedStation *sa = (const MergedStation *)a;
    const MergedStation *sb = (const MergedStation *)b;
    return strcmp(sa->name, sb->name);
}

int main(int argc, char **argv) {
    if (argc < 2) return 1;

    int fd = open(argv[1], O_RDONLY);
    if (fd < 0) return 1;

    struct stat st;
    if (fstat(fd, &st) < 0 || st.st_size == 0) {
        close(fd);
        printf("{}\n");
        return 0;
    }

    size_t file_size = st.st_size;
    const char *data = (const char *)mmap(NULL, file_size, PROT_READ, MAP_PRIVATE | MAP_POPULATE, fd, 0);
    if (data == MAP_FAILED) {
        close(fd);
        return 1;
    }
    madvise((void *)data, file_size, MADV_SEQUENTIAL);

    int num_threads = 6;
    if (file_size < 1000000) num_threads = 1;

    pthread_t threads[num_threads];
    ThreadArg args[num_threads];
    ThreadData tdata[num_threads];
    memset(tdata, 0, sizeof(tdata));

    size_t chunk_size = file_size / num_threads;

    for (int i = 0; i < num_threads; i++) {
        size_t start = (i == 0) ? 0 : i * chunk_size;
        if (i > 0) {
            while (start < file_size && data[start - 1] != '\n') {
                start++;
            }
        }
        size_t end = (i == num_threads - 1) ? file_size : (i + 1) * chunk_size;
        if (i < num_threads - 1) {
            while (end < file_size && data[end - 1] != '\n') {
                end++;
            }
        }

        args[i].data = data;
        args[i].start = start;
        args[i].end = end;
        args[i].total_size = file_size;
        args[i].td = &tdata[i];

        if (i > 0) {
            pthread_create(&threads[i], NULL, worker_thread, &args[i]);
        }
    }

    worker_thread(&args[0]);

    for (int i = 1; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    MergedStation merged[1024];
    int merged_count = 0;

    for (int t = 0; t < num_threads; t++) {
        for (int i = 0; i < TABLE_SIZE; i++) {
            HashEntry *e = &tdata[t].table[i];
            if (e->count == 0) continue;

            int found = 0;
            for (int m = 0; m < merged_count; m++) {
                if (merged[m].len == e->len && memcmp(merged[m].name, e->w, e->len) == 0) {
                    if (e->min < merged[m].min) merged[m].min = e->min;
                    if (e->max > merged[m].max) merged[m].max = e->max;
                    merged[m].sum += e->sum;
                    merged[m].count += e->count;
                    found = 1;
                    break;
                }
            }
            if (!found) {
                MergedStation *m = &merged[merged_count++];
                memcpy(m->name, e->w, e->len);
                m->name[e->len] = '\0';
                m->len = e->len;
                m->min = e->min;
                m->max = e->max;
                m->sum = e->sum;
                m->count = e->count;
            }
        }
    }

    qsort(merged, merged_count, sizeof(MergedStation), compare_merged);

    putchar('{');
    for (int i = 0; i < merged_count; i++) {
        MergedStation *st = &merged[i];
        double mean = (double)st->sum / (double)st->count / 10.0;
        double scaled = mean * 10.0;
        double r = (scaled >= 0) ? floor(scaled + 0.5) : ceil(scaled - 0.5);
        double v = r / 10.0;
        if (fabs(v) < 1e-9) v = 0.0;

        printf("%s=%.1f/%.1f/%.1f%s", st->name, st->min / 10.0, v, st->max / 10.0, (i + 1 < merged_count) ? ", " : "");
    }
    putchar('}');
    putchar('\n');

    munmap((void *)data, file_size);
    close(fd);
    return 0;
}

