#define TABLE_SIZE 4096
#define TABLE_MASK (TABLE_SIZE - 1)

typedef struct {
    uint64_t w[4];
    int32_t len;
    int32_t min;
    int32_t max;
    int32_t pad;
    int64_t sum;
    int64_t count;
} HashEntry __attribute__((aligned(64)));

typedef struct {
    HashEntry table[TABLE_SIZE];
    int count;
} ThreadData;

typedef struct {
    const char *data;
    size_t start;
    size_t end;
    size_t total_size;
    ThreadData *td;
} ThreadArg;

static __m256i MASK_TABLE[33];

__attribute__((constructor))
static void init_masks(void) {
    for (int i = 0; i <= 32; i++) {
        uint8_t mask_bytes[32];
        for (int j = 0; j < 32; j++) {
            mask_bytes[j] = (j < i) ? 0xFF : 0x00;
        }
        MASK_TABLE[i] = _mm256_loadu_si256((const __m256i *)mask_bytes);
    }
}

static inline void process_station(ThreadData *td, const uint64_t *w, int len, int temp) {
    uint64_t h = _mm_crc32_u64(_mm_crc32_u64(w[0], w[1]), w[2] ^ (uint64_t)len);
    int idx = (int)(h & TABLE_MASK);

    while (1) {
        HashEntry *e = &td->table[idx];
        if (__builtin_expect(e->count == 0, 0)) {
            e->w[0] = w[0];
            e->w[1] = w[1];
            e->w[2] = w[2];
            e->w[3] = w[3];
            e->len = len;
            e->min = temp;
            e->max = temp;
            e->sum = temp;
            e->count = 1;
            td->count++;
            return;
        }
        if (__builtin_expect(e->len == len && ((e->w[0] ^ w[0]) | (e->w[1] ^ w[1]) | (e->w[2] ^ w[2]) | (e->w[3] ^ w[3])) == 0, 1)) {
            if (temp < e->min) e->min = temp;
            if (temp > e->max) e->max = temp;
            e->sum += temp;
            e->count++;
            return;
        }
        idx = (idx + 1) & TABLE_MASK;
    }
}

static inline const char *process_one_line(ThreadData *td, const char *ptr, const char *file_end, const __m256i semi_vec) {
    if (__builtin_expect(ptr + 32 <= file_end, 1)) {
        __m256i raw = _mm256_loadu_si256((const __m256i *)ptr);
        __m256i cmp = _mm256_cmpeq_epi8(raw, semi_vec);
        int mask = _mm256_movemask_epi8(cmp);

        if (__builtin_expect(mask != 0, 1)) {
            int len = __builtin_ctz(mask);
            __m256i masked = _mm256_and_si256(raw, MASK_TABLE[len]);
            uint64_t w[4];
            _mm256_storeu_si256((__m256i *)w, masked);

            const char *p = ptr + len + 1;
            int neg = (*p == '-');
            p += neg;
            int temp;
            if (p[1] == '.') {
                temp = (p[0] - '0') * 10 + (p[2] - '0');
                p += 4;
            } else {
                temp = (p[0] - '0') * 100 + (p[1] - '0') * 10 + (p[3] - '0');
                p += 5;
            }
            if (neg) temp = -temp;

            process_station(td, w, len, temp);
            return p;
        }
    }

    const char *semi = memchr(ptr, ';', file_end - ptr);
    if (!semi) return file_end;
    int len = semi - ptr;
    uint64_t w[4] = {0};
    if (len <= 32) memcpy(w, ptr, len);
    else memcpy(w, ptr, 32);

    const char *p = semi + 1;
    int neg = (*p == '-');
    p += neg;
    int temp;
    if (p[1] == '.') {
        temp = (p[0] - '0') * 10 + (p[2] - '0');
        p += 4;
    } else {
        temp = (p[0] - '0') * 100 + (p[1] - '0') * 10 + (p[3] - '0');
        p += 5;
    }
    if (neg) temp = -temp;
    process_station(td, w, len, temp);
    return p;
}

static void *worker_thread_2way(void *arg) {
    ThreadArg *targ = (ThreadArg *)arg;
    const char *data = targ->data;
    size_t start = targ->start;
    size_t end = targ->end;
    size_t total_size = targ->total_size;
    const char *file_end = data + total_size;
    ThreadData *td = targ->td;

    const __m256i semi_vec = _mm256_set1_epi8(';');

    // Split chunk into 2 sub-slices
    size_t mid = start + (end - start) / 2;
    while (mid < end && data[mid - 1] != '\n') {
        mid++;
    }

    const char *p0 = data + start;
    const char *end0 = data + mid;
    const char *p1 = data + mid;
    const char *end1 = data + end;

    while (p0 < end0 && p1 < end1) {
        p0 = process_one_line(td, p0, file_end, semi_vec);
        p1 = process_one_line(td, p1, file_end, semi_vec);
    }

    while (p0 < end0) {
        p0 = process_one_line(td, p0, file_end, semi_vec);
    }
    while (p1 < end1) {
        p1 = process_one_line(td, p1, file_end, semi_vec);
    }

    return NULL;
}

