#define _GNU_SOURCE
#include <stdio.h>
#include <stdint.h>
#include <time.h>
#include <immintrin.h>

static inline int parse_A(const char *p, const char **next) {
    int neg = (*p == '-');
    p += neg;
    int temp;
    if (p[1] == '.') {
        temp = (p[0] - '0') * 10 + (p[2] - '0');
        p += 4;
    } else {
        temp = (p[0] - '0') * 100 + (p[1] - '0') * 10 + (p[3] - '0');
        p += 5;
    }
    *next = p;
    return neg ? -temp : temp;
}

static inline int parse_B(const char *p, const char **next) {
    uint64_t tw = *(const uint64_t *)p;
    int is_neg = ((tw & 0xFF) == 0x2D);
    tw >>= (is_neg << 3);
    int is_dot1 = ((tw & 0xFF00) == 0x2E00);
    int d0 = (int)(tw & 0x0F);
    int d1 = (int)((tw >> 8) & 0x0F);
    int d2 = (int)((tw >> 16) & 0x0F);
