    uint64_t w1;
    uint64_t w2;
    uint64_t w3;
    int32_t len;
    int32_t min;
    int32_t max;
    int32_t count;
    int64_t sum;
    uint64_t pad;
} HashEntry __attribute__((aligned(64)));

typedef struct {
    HashEntry table[TABLE_SIZE];
    int count;
} ThreadData;

typedef struct {
    const char *data;
    size_t start;
    size_t end;
    size_t total_size;
    ThreadData *td;
    int cpu_id;
} ThreadArg;

static inline void process_station_fast(ThreadData *td, uint64_t w0_masked, uint64_t w1_masked, uint64_t w2_masked, uint64_t w3_masked, int len, int temp, uint64_t h) {
    int idx = (int)(h & TABLE_MASK);

    while (1) {
        HashEntry *e = &td->table[idx];
        if (__builtin_expect(e->count == 0, 0)) {
            e->w0 = w0_masked;
            e->w1 = w1_masked;
            e->w2 = w2_masked;
            e->w3 = w3_masked;
            e->len = len;
            e->min = temp;
            e->max = temp;
            e->count = 1;
            e->sum = temp;
            td->count++;
            return;
        }
        if (__builtin_expect(((e->w0 ^ w0_masked) | (e->w1 ^ w1_masked) | (e->w2 ^ w2_masked) | (e->w3 ^ w3_masked) | (e->len ^ len)) == 0, 1)) {
            if (temp < e->min) e->min = temp;
            if (temp > e->max) e->max = temp;
            e->sum += temp;
            e->count++;
            return;
        }
        idx = (idx + 1) & TABLE_MASK;
    }
}

static inline const char *parse_and_process_line(ThreadData *td, const char *ptr, const char *file_end, const __m256i semi_vec) {
    if (__builtin_expect(ptr + 32 <= file_end, 1)) {
        __m256i raw = _mm256_loadu_si256((const __m256i *)ptr);
        __m256i cmp = _mm256_cmpeq_epi8(raw, semi_vec);
        int mask = _mm256_movemask_epi8(cmp);

        if (__builtin_expect(mask != 0, 1)) {
            int len = __builtin_ctz(mask);

            uint64_t w0 = *(const uint64_t *)ptr;
            uint64_t w1 = *(const uint64_t *)(ptr + 8);
            uint64_t w0_masked = _bzhi_u64(w0, len * 8);
            int shift1 = (len > 8) ? (len - 8) * 8 : 0;
            uint64_t w1_masked = _bzhi_u64(w1, shift1);
            uint64_t h = _mm_crc32_u64(w0_masked, w1_masked);
            uint64_t w2_masked = 0;
            uint64_t w3_masked = 0;

            if (__builtin_expect(len >= 16, 0)) {
                uint64_t w2 = *(const uint64_t *)(ptr + 16);
                int shift2 = (len > 16) ? (len - 16) * 8 : 0;
                w2_masked = _bzhi_u64(w2, shift2);
                h = _mm_crc32_u64(h, w2_masked);
                if (__builtin_expect(len >= 24, 0)) {
                    uint64_t w3 = *(const uint64_t *)(ptr + 24);
                    int shift3 = (len - 24) * 8;
                    w3_masked = _bzhi_u64(w3, shift3);
                    h = _mm_crc32_u64(h, w3_masked);
                }
            }

            const char *p = ptr + len + 1;
            int neg = (*p == '-');
            p += neg;
            int temp;
            if (p[1] == '.') {
                temp = (p[0] - '0') * 10 + (p[2] - '0');
                p += 4;
            } else {
                temp = (p[0] - '0') * 100 + (p[1] - '0') * 10 + (p[3] - '0');
                p += 5;
            }
            if (neg) temp = -temp;

            process_station_fast(td, w0_masked, w1_masked, w2_masked, w3_masked, len, temp, h);
            return p;
        }
    }

    const char *semi = memchr(ptr, ';', file_end - ptr);
    if (!semi) return file_end;
    int len = semi - ptr;
    uint64_t w[4] = {0};
    if (len <= 32) memcpy(w, ptr, len);
    else memcpy(w, ptr, 32);

    uint64_t h = _mm_crc32_u64(_mm_crc32_u64(w[0], w[1]), w[2] ^ (uint64_t)len);

    const char *p = semi + 1;
    int neg = (*p == '-');
    p += neg;
    int temp;
    if (p[1] == '.') {
        temp = (p[0] - '0') * 10 + (p[2] - '0');
        p += 4;
    } else {
        temp = (p[0] - '0') * 100 + (p[1] - '0') * 10 + (p[3] - '0');
        p += 5;
    }
    if (neg) temp = -temp;
    process_station_fast(td, w[0], w[1], w[2], w[3], len, temp, h);
    return p;
}

static void *worker_thread_2way(void *arg) {
    ThreadArg *targ = (ThreadArg *)arg;
    if (targ->cpu_id >= 0) {
        cpu_set_t cpuset;
        CPU_ZERO(&cpuset);
        CPU_SET(targ->cpu_id, &cpuset);
        pthread_setaffinity_np(pthread_self(), sizeof(cpu_set_t), &cpuset);
    }

    const char *data = targ->data;
    size_t start = targ->start;
    size_t end = targ->end;
    size_t total_size = targ->total_size;
    const char *file_end = data + total_size;
    ThreadData *td = targ->td;

    const __m256i semi_vec = _mm256_set1_epi8(';');

    size_t mid = start + (end - start) / 2;
    while (mid < end && data[mid - 1] != '\n') mid++;

    const char *p0 = data + start;
    const char *end0 = data + mid;
    const char *p1 = data + mid;
    const char *end1 = data + end;

    while (p0 < end0 && p1 < end1) {
        p0 = parse_and_process_line(td, p0, file_end, semi_vec);
        p1 = parse_and_process_line(td, p1, file_end, semi_vec);
    }

    while (p0 < end0) p0 = parse_and_process_line(td, p0, file_end, semi_vec);
    while (p1 < end1) p1 = parse_and_process_line(td, p1, file_end, semi_vec);

    return NULL;
}

typedef struct {
    char name[64];
    int len;
    int min;
    int max;
    int64_t sum;
    int64_t count;
} MergedStation;

static int compare_merged(const void *a, const void *b) {
    const MergedStation *sa = (const MergedStation *)a;
    const MergedStation *sb = (const MergedStation *)b;
    return strcmp(sa->name, sb->name);
}

int main(int argc, char **argv) {
    if (argc < 2) return 1;

    int fd = open(argv[1], O_RDONLY);
    if (fd < 0) return 1;

    struct stat st;
    if (fstat(fd, &st) < 0 || st.st_size == 0) {
        close(fd);
        printf("{}\n");
        return 0;
    }

    size_t file_size = st.st_size;
    const char *data = (const char *)mmap(NULL, file_size, PROT_READ, MAP_SHARED, fd, 0);
    if (data == MAP_FAILED) {
        close(fd);
        return 1;
    }
    madvise((void *)data, file_size, MADV_SEQUENTIAL | MADV_HUGEPAGE);

    int num_threads = 6;
    if (file_size < 1000000) num_threads = 1;

    pthread_t threads[num_threads];
    ThreadArg args[num_threads];
    ThreadData tdata[num_threads];
    memset(tdata, 0, sizeof(tdata));

    size_t chunk_size = file_size / num_threads;

    for (int i = 0; i < num_threads; i++) {
        size_t start = (i == 0) ? 0 : i * chunk_size;
        if (i > 0) {
            while (start < file_size && data[start - 1] != '\n') {
                start++;
            }
        }
        size_t end = (i == num_threads - 1) ? file_size : (i + 1) * chunk_size;
        if (i < num_threads - 1) {
            while (end < file_size && data[end - 1] != '\n') {
                end++;
            }
        }

        args[i].data = data;
        args[i].start = start;
        args[i].end = end;
        args[i].total_size = file_size;
        args[i].td = &tdata[i];
        args[i].cpu_id = i;

        if (i > 0) {
            pthread_create(&threads[i], NULL, worker_thread_2way, &args[i]);
        }
    }

    worker_thread_2way(&args[0]);

    for (int i = 1; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    MergedStation merged[1024];
    int merged_count = 0;

    for (int t = 0; t < num_threads; t++) {
        for (int i = 0; i < TABLE_SIZE; i++) {
            HashEntry *e = &tdata[t].table[i];
            if (e->count == 0) continue;

            uint64_t name_w[4] = {e->w0, e->w1, e->w2, e->w3};
            char *name_str = (char *)name_w;

            int found = 0;
            for (int m = 0; m < merged_count; m++) {
                if (merged[m].len == e->len && memcmp(merged[m].name, name_str, e->len) == 0) {
                    if (e->min < merged[m].min) merged[m].min = e->min;
                    if (e->max > merged[m].max) merged[m].max = e->max;
                    merged[m].sum += e->sum;
                    merged[m].count += e->count;
                    found = 1;
                    break;
                }
            }
            if (!found) {
                MergedStation *m = &merged[merged_count++];
                memcpy(m->name, name_str, e->len);
                m->name[e->len] = '\0';
                m->len = e->len;
                m->min = e->min;
                m->max = e->max;
                m->sum = e->sum;
                m->count = e->count;
            }
        }
    }

    qsort(merged, merged_count, sizeof(MergedStation), compare_merged);

    putchar('{');
    for (int i = 0; i < merged_count; i++) {
        MergedStation *st = &merged[i];
        double mean = (double)st->sum / (double)st->count / 10.0;
        double scaled = mean * 10.0;
        double r = (scaled >= 0) ? floor(scaled + 0.5) : ceil(scaled - 0.5);
        double v = r / 10.0;
        if (fabs(v) < 1e-9) v = 0.0;

        printf("%s=%.1f/%.1f/%.1f%s", st->name, st->min / 10.0, v, st->max / 10.0, (i + 1 < merged_count) ? ", " : "");
    }
    putchar('}');
    putchar('\n');

    munmap((void *)data, file_size);
    close(fd);
    return 0;
}

