void c_round(int64_t sum, int64_t count, char *out) {
    double scaled = (double)sum / (double)count;
    double r = (scaled >= 0) ? floor(scaled + 0.5) : ceil(scaled - 0.5);
    double v = r / 10.0;
    if (fabs(v) < 1e-9) v = 0.0;
