            c_round(sum, count, buf_c);
            // Verify scaled matches
            double mean = (double)sum / (double)count / 10.0;
            double scaled = mean * 10.0;
            double r = (scaled >= 0) ? floor(scaled + 0.5) : ceil(scaled - 0.5);
